一个废物的算法竞赛模板，没有目录，只有乱乱的内容 永远记不住的ta们可以直接用 &#x3D;（赋值运算符） 进行深拷贝。 vector 动态数组，支持随机访问。 尾部插入 &#x2F; 删除高效（均摊 O (1)），中间插入 &#x2F; 删除较慢（O (n)）。 内存连续，可能需要重新分配内存（导致元素复制） 123456789101112131415161718192021222324252627282930vector&lt;int&gt; v = &#123;1, 2, 3&#125;;vector&lt;vector&lt;int&gt;&gt; a(N, vector&lt;int&gt;(N)); //（二维）// 容量v.size(); // 返回元素个数v.capacity(); // 返回当前分配的容量v.reserve(10);// 预分配至少10个元素的空间v.resize(5); // 调整大小为5个元素v.empty(); // 判断是否为空// 访问v[2]; // 随机访问（不检查边界）v.at(2); // 随机访问（检查边界，越界抛出异常）v.front(); // 返回第一个元素v.back(); // 返回最后一个元素// 修改v.push_back(4); // 尾部插入v.pop_back(); // 尾部删除v.insert(v.begin()+1, 5); // 在第二个位置插入5v.erase(v.begin()); // 删除第一个元素v.clear(); // 清空所有元素//可以使用sort：sort(v.begin(),v.end());vector&lt;int&gt; a = &#123;1, 2, 3&#125;;vector&lt;int&gt; b;b = a; // 深拷贝赋值：b 成为 a 的独立副本 deque 双端队列，支持头尾高效插入 &#x2F; 删除（O (1)）。 随机访问效率略低于vector。 内部由多个固定大小的数组组成，避免了vector的内存重分配问题。 12345678910std::deque&lt;int&gt; dq = &#123;1, 2, 3&#125;;// 相比vector新增的函数dq.push_front(0); // 头部插入dq.pop_front(); // 头部删除// 其他函数与vector类似dq.size();dq[1];dq.insert(dq.begin()+1, 4); list 双向链表，任意位置插入 &#x2F; 删除高效（O (1)）。 不支持随机访问（只能顺序遍历）。 内存不连续，每个元素包含前后指针。 1234567891011121314151617std::list&lt;int&gt; lst = &#123;1, 2, 3&#125;;// 相比vector新增的函数lst.push_front(0); // 头部插入lst.pop_front(); // 头部删除lst.splice(lst.end(), lst2); // 将lst2的所有元素移动到lst末尾lst.sort(); // 排序lst.unique(); // 去重（需相邻元素相同）lst.merge(lst2); // 合并两个已排序的list// 不支持随机访问// lst[0]; // 错误！// 遍历for (auto it = lst.begin(); it != lst.end(); ++it) &#123; // ...&#125; set 有序集合，元素唯一，基于红黑树实现。 插入、删除、查找均为 O (log n) 时间复杂度。 元素自动按升序排列（可自定义比较函数）。(从小到大) 123456789101112131415161718192021std::set&lt;int&gt; s = &#123;3, 1, 2&#125;; // 自动排序为 &#123;1, 2, 3&#125;// 查找s.find(2); // 返回迭代器，若不存在则返回s.end()s.count(2); // 返回元素个数（0或1）s.lower_bound(2); // 返回第一个&gt;=2的元素迭代器s.upper_bound(2); // 返回第一个&gt;2的元素迭代器// 修改s.insert(4); // 插入元素s.erase(2); // 删除元素s.clear();//清空for (auto it = s.begin(); it != s.end(); ++it) &#123; cout &lt;&lt; *it &lt;&lt; &quot; &quot;; &#125;//利用迭代器遍历auto it = s.find(4);it = s.erase(it); // erase返回下一个迭代器，直接赋值给it map 有序键值对，键唯一，基于红黑树实现。 插入、删除、查找、单点访问均为 O (log n) 时间复杂度。 元素按键升序排列。 123456789101112131415161718192021222324252627282930313233map&lt;string, int&gt; m = &#123;&#123;&quot;one&quot;, 1&#125;, &#123;&quot;two&quot;, 2&#125;&#125;;//声明 map 时指定比较器为 greater&lt;int&gt;（int 是键的类型）//从而从大到小排序map&lt;int, string, greater&lt;int&gt;&gt; myMap;// 访问m[&quot;one&quot;]; // 通过键访问值（若键不存在则创建）m.at(&quot;one&quot;); // 通过键访问值（若键不存在则抛出异常）// 查找m.find(&quot;one&quot;); // 返回迭代器m.count(&quot;one&quot;); // 返回键的个数（0或1、这里）// 修改m.insert(&#123;&quot;three&quot;, 3&#125;); // 插入键值对m[&quot;four&quot;] = 4; // 插入或更新m.erase(&quot;one&quot;); // 删除键值对//更为常见的遍历方法for(auto &amp;[x,y]:m)&#123; cout&lt;&lt;x&lt;&lt;&quot; &quot;&lt;&lt;y&lt;&lt;&quot;
&quot;;&#125; // 正向遍历for (map&lt;int, string&gt;::iterator it = myMap.begin(); it != myMap.end(); ++it) &#123; cout &lt;&lt; &quot;key: &quot; &lt;&lt; it-&gt;first &lt;&lt; &quot;, value: &quot; &lt;&lt; it-&gt;second &lt;&lt; endl;&#125;// 反向遍历for (map&lt;int, string&gt;::reverse_iterator rit = myMap.rbegin(); rit != myMap.rend(); ++rit) &#123; cout &lt;&lt; &quot;key: &quot; &lt;&lt; rit-&gt;first &lt;&lt; &quot;, value: &quot; &lt;&lt; rit-&gt;second &lt;&lt; endl;&#125; multiset multimap 允许重复元素或键，其他特性与set和map相同 12345678std::multiset&lt;int&gt; ms = &#123;1, 2, 2, 3&#125;;ms.count(2); // 返回2std::multimap&lt;std::string, int&gt; mm = &#123;&#123;&quot;one&quot;, 1&#125;, &#123;&quot;one&quot;, 10&#125;&#125;;auto range = mm.equal_range(&quot;one&quot;); // 返回键为&quot;one&quot;的元素范围for (auto it = range.first; it != range.second; ++it) &#123; // ...&#125; unordered_set 无序集合，元素唯一，基于哈希表实现。 平均 O (1) 时间复杂度的插入、删除、查找。 内存占用较大，且可能需要重新哈希（rehash）。 1234567891011std::unordered_set&lt;int&gt; us = &#123;3, 1, 2&#125;;// 基本与set相同，但不支持lower_bound/upper_boundus.find(2);us.count(2);us.insert(4);us.erase(2);// 哈希表特有的函数us.bucket_count(); // 返回桶的数量us.load_factor(); // 返回负载因子 unordered_map 无序键值对，键唯一，基于哈希表实现。（不建议使用 极大可能被特定数据卡掉） 平均 O (1) 时间复杂度的插入、删除、查找。 12345678std::unordered_map&lt;std::string, int&gt; um = &#123;&#123;&quot;one&quot;, 1&#125;, &#123;&quot;two&quot;, 2&#125;&#125;;// 基本与map相同，但不支持lower_bound/upper_boundum[&quot;one&quot;];um.find(&quot;one&quot;);um.count(&quot;one&quot;);um.insert(&#123;&quot;three&quot;, 3&#125;);um.erase(&quot;one&quot;); stack 后进先出（LIFO）栈，默认基于deque实现。 只允许在栈顶操作。 1234567std::stack&lt;int&gt; st;st.push(1); // 入栈st.top(); // 返回栈顶元素st.pop(); // 出栈st.empty(); // 判断是否为空st.size(); // 返回元素个数 queue 先进先出（FIFO）队列，默认基于deque实现。 支持队首出队、队尾入队。 没有q.clear() 1234567891011std::queue&lt;int&gt; q;q.push(1); // 入队q.front(); // 返回队首元素q.back(); // 返回队尾元素q.pop(); // 出队q.empty(); // 判断是否为空q.size(); // 返回元素个数q=queue&lt;int&gt;();//临时对象替换（用于清空queue） priority_queue 优先队列，最大 &#x2F; 最小元素优先出队，默认基于vector和堆实现。 默认按元素值降序排列（大的在队首）。 无法直接查找元素 1234567891011// 大顶堆（默认）std::priority_queue&lt;int&gt; pq;// 小顶堆std::priority_queue&lt;int, std::vector&lt;int&gt;, std::greater&lt;int&gt;&gt; min_pq;pq.push(3); // 入队pq.top(); // 返回队首元素（最大值）pq.pop(); // 出队pq.empty(); // 判断是否为空pq.size(); // 返回元素个数 所有容器都支持以下操作： begin(), end()：返回指向首尾元素的迭代器。 rbegin(), rend()：返回指向首尾元素的反向迭代器。 empty(), size()：判断容器是否为空、返回元素个数。 clear()：清空容器 其他关于stl容器你可能需要的lower_bound函数时间复杂度logn。在有序区间内，查找第一个大于等于（≥）目标值的元素，返回指向该元素的迭代器；若未找到，则返回区间的尾迭代器（常见于 vector、array、set、map（对键的查找） 等） 1234vector&lt;int&gt; vec = &#123;1, 3, 4, 6, 8, 10&#125;; // 必须是升序有序！ int target = 5; // 查找第一个 ≥ 5 的元素 auto it = lower_bound(vec.begin(), vec.end(), target); upper_bound函数和楼上类似，但是是查找第一个大于的元素 12auto upper = std::upper_bound(vec.begin(), vec.end(), target);std::cout &lt;&lt; (upper - vec.begin()) &lt;&lt; std::endl; 结构体定义比较函数定义后可直接使用sort、set、map等。 123456789struct Node&#123; int l,r; bool operator&lt;(const Node other)const&#123; if(this-&gt;l==other.l)&#123; return this-&gt;r&lt;other.r; &#125; return this-&gt;l&lt;other.l; &#125;//小的在前 pair1. 定义与初始化1234567891011121314#include &lt;utility&gt; // 必须包含此头文件#include &lt;string&gt;// 方式1：默认构造std::pair&lt;int, std::string&gt; p1; // 默认初始化为 &#123;0, &quot;&quot;&#125;// 方式2：直接赋值std::pair&lt;int, std::string&gt; p2(1, &quot;hello&quot;);// 方式3：使用 make_pair() 函数（自动推导类型）auto p3 = std::make_pair(2, &quot;world&quot;);// 方式4：C++11 列表初始化std::pair&lt;int, std::string&gt; p4&#123;3, &quot;cpp&quot;&#125;; 2. 访问元素1234567// 通过 first 和 second 成员访问int num = p2.first; // 获取第一个元素（1）std::string str = p2.second; // 获取第二个元素（&quot;hello&quot;）// 修改元素p2.first = 10;p2.second = &quot;hi&quot;; 3. 比较操作pair 支持比较运算符（&lt;, &gt;, == 等），按字典序比较： 123456std::pair&lt;int, char&gt; p1(1, &#x27;a&#x27;);std::pair&lt;int, char&gt; p2(2, &#x27;b&#x27;);std::pair&lt;int, char&gt; p3(1, &#x27;c&#x27;);p1 &lt; p2; // true（先比较 first，1 &lt; 2）p1 &lt; p3; // true（first 相同，再比较 second，&#x27;a&#x27; &lt; &#x27;c&#x27;） 4.自定义排序12345// 按 second 降序排序std::sort(students.begin(), students.end(), [](const auto&amp; a, const auto&amp; b) &#123; return a.second &gt; b.second; // 年龄从大到小 &#125;); string123456std::string s1; // 默认空字符串std::string s2 = &quot;Hello&quot;; // 直接初始化std::string s3(&quot;World&quot;); // 构造函数初始化std::string s4 = s2 + &quot; &quot; + s3; // 拼接初始化std::string s5(5, &#x27;a&#x27;); // 重复字符：&quot;aaaaa&quot;//数字转字母：char c=&#x27;a&#x27;+2 12s.length(); // 或 s.size()，返回字符串长度s.empty(); // 判断是否为空 12s[0]; // 下标访问（不检查越界）s.at(0); // 安全访问（越界时抛出异常） 123s += &quot;!&quot;; // 追加字符/字符串s.append(&quot; World&quot;); // 追加字符串s.push_back(&#x27;!&#x27;); // 追加单个字符 123s1 == s2; // 内容相等比较s1 != s2; // 内容不等比较s1 &lt; s2; // 字典序比较 1s.substr(pos, len); // 从 pos 开始的 len 个字符 12345s.find(&quot;ll&quot;); // 查找子串，返回首次出现的位置（未找到返回 npos）s.rfind(&quot;l&quot;); // 从后往前查找s.find_first_of(&quot;aeiou&quot;); // 查找首次出现元音的位置//find返回的值是数字或string::npos 123s.insert(pos, &quot;text&quot;); // 在 pos 处插入字符串s.erase(pos, len); // 删除从 pos 开始的 len 个字符s.clear(); // 清空字符串 1s.replace(pos, len, &quot;new&quot;); // 替换从 pos 开始的 len 个字符为 &quot;new&quot; 12const char* c_str = s.c_str(); // 转为 const char*std::string s = std::string(c_str); // 从 const char* 构造 123#include &lt;algorithm&gt;std::transform(s.begin(), s.end(), s.begin(), ::toupper); // 转大写std::transform(s.begin(), s.end(), s.begin(), ::tolower); // 转小写 1234567// string → 数值int num = std::stoi(s); // 转为 intdouble d = std::stod(s); // 转为 double// 数值 → stringstd::string s = std::to_string(42); // 整数转字符串//浮点数（默认保留六位小数）、负数也能转 12for (char c : s) &#123; ... &#125; // 范围-based for 循环for (size_t i = 0; i &lt; s.length(); i++) &#123; ... &#125; // 下标循环 1234567891011#include&lt;bits/stdc++.h&gt;#define int long longusing namespace std;#define IO ios::sync_with_stdio(false);cin.tie(0);typedef long long ll;typedef pair &lt;int , int&gt; pii; 高精加12345678910111213141516171819202122232425262728293031323334353637383940414243#include &lt;iostream&gt;#include &lt;vector&gt;#include &lt;string&gt;#include &lt;algorithm&gt;using namespace std;string add(string a, string b) &#123; // 确保a是较长的字符串 if (a.size() &lt; b.size()) swap(a, b); reverse(a.begin(), a.end()); reverse(b.begin(), b.end()); vector&lt;int&gt; res; int carry = 0; for (int i = 0; i &lt; a.size(); i++) &#123; int digitA = a[i] - &#x27;0&#x27;; int digitB = (i &lt; b.size()) ? b[i] - &#x27;0&#x27; : 0; int sum = digitA + digitB + carry; carry = sum / 10; res.push_back(sum % 10); &#125; if (carry) res.push_back(carry); string ans; for (int i = res.size() - 1; i &gt;= 0; i--) &#123; ans += char(res[i] + &#x27;0&#x27;); &#125; return ans;&#125;int main() &#123; string num1, num2; cout &lt;&lt; &quot;Enter first number: &quot;; cin &gt;&gt; num1; cout &lt;&lt; &quot;Enter second number: &quot;; cin &gt;&gt; num2; string result = add(num1, num2); cout &lt;&lt; &quot;Sum: &quot; &lt;&lt; result &lt;&lt; endl; return 0;&#125; 高精乘12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849#include &lt;iostream&gt;#include &lt;vector&gt;#include &lt;string&gt;#include &lt;algorithm&gt;using namespace std;string multiply(string num1, string num2) &#123; // 处理特殊情况：乘数为0 if (num1 == &quot;0&quot; || num2 == &quot;0&quot;) return &quot;0&quot;; int n = num1.size(), m = num2.size(); // 结果数组，最多有n+m位 vector&lt;int&gt; res(n + m, 0); // 从低位开始计算（字符串从后向前遍历） for (int i = n - 1; i &gt;= 0; i--) &#123; for (int j = m - 1; j &gt;= 0; j--) &#123; int mul = (num1[i] - &#x27;0&#x27;) * (num2[j] - &#x27;0&#x27;); int p1 = i + j, p2 = i + j + 1; // p2是低位位置，p1是高位位置 // 累加到结果数组 int sum = mul + res[p2]; res[p2] = sum % 10; // 当前位 res[p1] += sum / 10; // 进位 &#125; &#125; // 将结果数组转换为字符串 string ans; for (int num : res) &#123; // 跳过前导零（但保留最后一位） if (ans.empty() &amp;&amp; num == 0) continue; ans += to_string(num); &#125; return ans.empty() ? &quot;0&quot; : ans; // 处理结果全零的情况&#125;int main() &#123; string num1, num2; cout &lt;&lt; &quot;Enter first number: &quot;; cin &gt;&gt; num1; cout &lt;&lt; &quot;Enter second number: &quot;; cin &gt;&gt; num2; string result = multiply(num1, num2); cout &lt;&lt; &quot;Product: &quot; &lt;&lt; result &lt;&lt; endl; return 0;&#125; 随机数123456789101112131415#include &lt;iostream&gt;#include &lt;chrono&gt;#include &lt;random&gt;using namespace std;int main()&#123;//unsigned seed =std::chrono::system_clock::now().time_since_epoch().count();//mt19937 rand_num(seed); 方法一random_device divc;mt19937 rand_num(divc()); //方法二：Linux真随机数uniform_int_distribution&lt;long long&gt; dist(0, 1000000000);cout &lt;&lt; dist(rand_num) &lt;&lt; endl;return 0;&#125; 迪杰斯特拉算法12345678910111213141516171819202122232425262728293031323334353637383940#include&lt;bits/stdc++.h&gt;using namespace std;typedef long long int ll;int n,m,s;vector&lt;pair&lt;int,ll&gt;&gt; t[100002];vector&lt;ll&gt; dis(100002,1e9+1);bool vis[100002];int main()&#123; cin&gt;&gt;n&gt;&gt;m&gt;&gt;s; int i; ll u,v,w; for(i=0;i&lt;m;i++)&#123; cin&gt;&gt;u&gt;&gt;v&gt;&gt;w; t[u].push_back(&#123;v,w&#125;); &#125; priority_queue&lt;pair&lt;ll,int&gt;,vector&lt;pair&lt;ll,int&gt;&gt;,greater&lt;pair&lt;ll,int&gt;&gt;&gt; dui; dui.push(&#123;0,1&#125;); dis[1]=0; while(!dui.empty())&#123; int v=dui.top().second; dui.pop(); if(vis[v])&#123; continue; &#125; vis[v]=true; for(auto [u,len] :t[v])&#123; if(dis[u]&gt;dis[v]+len)&#123; dis[u]=dis[v]+len; dui.push(&#123;dis[u],u&#125;); &#125; &#125; &#125; for(i=1;i&lt;=n;i++)&#123; cout&lt;&lt;dis[i]&lt;&lt;&quot; &quot;; &#125; return 0;&#125; 加速1234567891011121314151617181920212223242526//手动o2、o3、ofast优化#pragma GCC optimize(2)#pragma GCC optimize(3)#pragma GCC optimize(&quot;Ofast,unroll-loops&quot;)template&lt;typename type&gt;//快读inline void read(type &amp;x)&#123; x=0;static bool flag(0);char ch=getchar(); while(!isdigit(ch)) flag=ch==&#x27;-&#x27;,ch=getchar(); while(isdigit(ch)) x=(x&lt;&lt;1)+(x&lt;&lt;3)+(ch^48),ch=getchar(); flag?x=-x:0;&#125;template&lt;typename type&gt;//快写inline void write(type x,bool mode=1)//0为空格，1为换行&#123; x&lt